  'https://news.google.com/rss/search?q=FMCG+acquisition+deal&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=consumer+goods+merger+acquisition&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=food+beverage+acquisition+billion&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=FMCG+private+equity+investment&hl=en-US&gl=US&ceid=US:en',
  // Key global brands
  'https://news.google.com/rss/search?q=Unilever+acquisition+deal+2026&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=Nestle+merger+acquisition+deal&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=PepsiCo+acquisition+deal&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=Coca-Cola+acquisition+investment&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=Procter+Gamble+acquisition&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=Mars+Mondelez+Kraft+acquisition&hl=en-US&gl=US&ceid=US:en',
  // India FMCG
  'https://news.google.com/rss/search?q=India+FMCG+acquisition+deal&hl=en-IN&gl=IN&ceid=IN:en',
  'https://news.google.com/rss/search?q=HUL+Dabur+Marico+ITC+acquisition&hl=en-IN&gl=IN&ceid=IN:en',
  'https://news.google.com/rss/search?q=Tata+Consumer+acquisition+India&hl=en-IN&gl=IN&ceid=IN:en',
  // Deal types
  'https://news.google.com/rss/search?q=FMCG+divestiture+spin-off+brand+sale&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=CPG+brand+acquisition+joint+venture&hl=en-US&gl=US&ceid=US:en',
];

return feeds.map(url => ({ json: { feed_url: url } }));

const crypto = require('crypto');

return items.map(item => {
  const d = item.json;
  const url = (d.link || d.url || '').trim();
  const title = (d.title || '').replace(/<[^>]*>/g, '').trim();
  const source = d.creator || d.author || extractDomain(url);
  const publishedAt = d.pubDate || d.isoDate || d.date || new Date().toISOString();
  const content = (d.contentSnippet || d.content || d.summary || '').replace(/<[^>]*>/g, '').substring(0, 2000);

  // Hash URL for dedup — stable identifier
  const contentHash = crypto.createHash('md5').update(url).digest('hex');

  return {
    json: {
      title,
      url,
      content,
      source,
      published_at: new Date(publishedAt).toISOString(),
      content_hash: contentHash,
      ingestion_source: 'rss',
      raw_feed_url: item.json.feedUrl || null,
    }
  };
}).filter(item => item.json.url && item.json.title);

function extractDomain(url) {
  try { return new URL(url).hostname.replace('www.', ''); } catch { return 'unknown'; }
}

const crypto = require('crypto');

const response = items[0].json;
const articles = response.articles || [];

if (!articles.length) return [];

return articles.map(a => {
  const url = (a.url || '').trim();
  const contentHash = crypto.createHash('md5').update(url).digest('hex');
  return {
    json: {
      title: (a.title || '').trim(),
      url,
      content: (a.description || a.content || '').substring(0, 2000),
      source: a.source?.name || extractDomain(url),
      published_at: a.publishedAt || new Date().toISOString(),
      content_hash: contentHash,
      ingestion_source: 'newsapi',
      raw_feed_url: null,
    }
  };
}).filter(item => item.json.url && item.json.title);

function extractDomain(url) {
  try { return new URL(url).hostname.replace('www.', ''); } catch { return 'unknown'; }
}

// Remove exact URL duplicates within this batch before DB write
const seen = new Set();
const unique = [];

for (const item of items) {
  const hash = item.json.content_hash;
  if (hash && !seen.has(hash)) {
    seen.add(hash);
    unique.push(item);
  }
}

console.log(`Ingested: ${items.length} → Unique: ${unique.length}`);
return unique;

// Log completion — update pipeline_runs via Supabase REST API
const total = items.length;
console.log(`Workflow A complete. Records inserted/attempted: ${total}`);
return [{ json: { status: 'success', records_ingested: total, timestamp: new Date().toISOString() } }];
